import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 250010;
    static long[] fact = new long[MAX_SIZE];
    static long[] invFact = new long[MAX_SIZE];
    static long[][] dpTable = new long[30][MAX_SIZE];
    static int[] bitCount = new int[MAX_SIZE];
    static long totalCount, maxLimit, modVal;

    static long nCr(int n, int r) {
        return fact[n] * invFact[n - r] % modVal * invFact[r] % modVal;
    }

    static void update(LongWrapper x, long y) {
        x.value += y;
        if (x.value >= modVal) x.value -= modVal;
    }

    static class LongWrapper {
        long value;
        LongWrapper(long v) { this.value = v; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalCount = sc.nextLong();
        maxLimit = sc.nextLong();
        modVal = sc.nextLong();

        fact[0] = 1;
        invFact[0] = 1;
        fact[1] = 1;
        invFact[1] = 1;

        for (int i = 2; i <= totalCount; i++) {
            long q = modVal / i;
            long r = modVal - i * q;
            fact[i] = fact[i - 1] * i % modVal;
            invFact[i] = modVal - (q * invFact[(int) r] % modVal);
        }

        for (int i = 2; i <= totalCount; i++) {
            invFact[i] = invFact[i - 1] * invFact[i] % modVal;
        }

        long result = 1;
        for (int i = 1; i <= totalCount; i++) {
            result = result * maxLimit % modVal;
        }

        for (int i = 1; i <= totalCount; i++) {
            bitCount[i] = bitCount[i >> 1] + (i & 1);
        }

        if (totalCount % 2 == 1) {
            System.out.println(result);
            sc.close();
            return;
        }

        dpTable[0][0] = 1;
        int maxBits = (int) Math.min(bitCount[(int) totalCount], maxLimit);

        for (int i = 0; i < maxBits; i++) {
            for (int j = 0; j < totalCount; j++) {
                if (dpTable[i][j] == 0) continue;
                int mask = (int) (totalCount ^ j);
                for (int k = mask; k > j; k = (k - 1) & mask) {
                    int r = k | j;
                    LongWrapper dw = new LongWrapper(dpTable[i][j]);
                    update(dw, invFact[k]);
                    dpTable[i + 1][r] = (dpTable[i + 1][r] + dw.value) % modVal;
                }
            }
        }

        for (int i = 1; i <= maxLimit; i++) {
            long temp = dpTable[i][(int) totalCount] * fact[(int) maxLimit] % modVal
                    * invFact[(int) (maxLimit - i)] % modVal * fact[(int) totalCount] % modVal;
            result -= temp;
        }

        result = (modVal + result % modVal) % modVal;
        System.out.println(result);
        sc.close();
    }
}

